import{_ as r,a0 as l,w as i,s,ao as o,I as e,x as n,a1 as u,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Ubuntu 14.04下升級GNOME至3.12 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 14.04下升級GNOME至3.12 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 14.04下升級GNOME至3.12 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 14.04下升級GNOME至3.12 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How to Upgrade to GNOME 3.12 in Ubuntu 14.04","title":"Ubuntu 14.04下升級GNOME至3.12","tag":"201405","desc":""},"relativePath":"201405/How to Upgrade to GNOME 3.12 in Ubuntu 14.04.md","filePath":"[post].md"}'),d={name:"201405/How to Upgrade to GNOME 3.12 in Ubuntu 14.04.md"};function g(m,t,b,N,M,E){const a=l("Link");return i(),s("div",null,[t[17]||(t[17]=o('<h1 id="ubuntu-14-04下升級gnome至3-12" tabindex="-1">Ubuntu 14.04下升級GNOME至3.12 <a class="header-anchor" href="#ubuntu-14-04下升級gnome至3-12" aria-label="Permalink to “Ubuntu 14.04下升級GNOME至3.12”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/03/Screen-Shot-2014-03-26-at-21.53.58-350x200.png" alt="讀者可以直接升級GNOME至3.12-但並不建議這麼做"></p><p><strong>如果您的系統最近已升級至Ubuntu GNOME 14.04 LTS版本，那麼擁有穩定獨立的GNOME Shell無疑是您最佳的選擇</strong></p><p>但我認為比較保守的用户會傾向於選擇默認向新手提供的穩定版本。你真想要了解如何在Ubuntu14.04升級GNOME至3.12嗎？</p><p>好的，接下來我將向你介紹如何完成。首先，我們需要先了解下來龍去脈。</p><h4 id="默認採用gnome-3-10的原因" tabindex="-1">默認採用GNOME 3.10的原因 <a class="header-anchor" href="#默認採用gnome-3-10的原因" aria-label="Permalink to “默認採用GNOME 3.10的原因”">​</a></h4><p>GNOME 3.12在3月底發佈後引發了一陣轟動而天馬行空的評論。儘管其上個月發佈的版本在Ubuntu 14.04 LTS版本之前已經逐步趨於穩定，卻仍不能從14.04包中直接安裝，這是為什麼呢?</p><p>簡單來説在開發週期中它出現太晚以至於沒有充足的時間來對它進行審查、測試並確保它已經更新至LTS命令發佈支持的標準及用户期望。默認至舊版發佈的3.10是有意義的，因為有專門的計劃來確保測試完整。</p><p>所以，正因為這樣<strong>不建議升級GNOME至3.12</strong>。</p><p>這樣清楚了嗎？接下來，讓我們進入下一個階段。</p><h3 id="如何在ubuntu-14-04升級gnome至3-12" tabindex="-1">如何在Ubuntu 14.04升級GNOME至3.12### <a class="header-anchor" href="#如何在ubuntu-14-04升級gnome至3-12" aria-label="Permalink to “如何在Ubuntu 14.04升級GNOME至3.12###”">​</a></h3><h4 id="確保你正在運行的gnome版本是3-10" tabindex="-1">確保你正在運行的GNOME版本是3.10 <a class="header-anchor" href="#確保你正在運行的gnome版本是3-10" aria-label="Permalink to “確保你正在運行的GNOME版本是3.10”">​</a></h4><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/05/gr.jpg" alt=""></p><p>為確保正確遵循本嚮導，需要在最新版本的Ubuntu(14.04 LTS)或Ubuntu GNOME下繼續操作。如果不是最新版本的話，請停止操作；你需要升級後再繼續。如果不這樣做，接下來將會有一系列複雜又麻煩的事情需要解決。</p><p>若你運行的是Ubuntu常規版本（例如帶有Unity），那麼需要在開始以下步驟前從Ubuntu軟件中心安裝GNOME 3.10。</p><p>按以下給出的鏈接選項準備好安裝程序。</p><ul><li>[Ubuntu14.04LTS版本下安裝GNOME3.10]</li></ul><h4 id="增加gnome-3-12-ppa" tabindex="-1">增加GNOME 3.12 PPA <a class="header-anchor" href="#增加gnome-3-12-ppa" aria-label="Permalink to “增加GNOME 3.12 PPA”">​</a></h4><p>起初人們預想的是GNOME 3.12將會由標準GNOME Team PPA隨着 14.04 LTS 發佈。但3個星期過去了，卻什麼都沒有。這是因為一些小的3.10軟件包仍然沒有跟着發佈最新的3.12的包。</p>',19)),e("p",null,[t[1]||(t[1]=n("然而，",-1)),u(a,{href:"https://launchpad.net/~gnome3-team/+archive/gnome3-staging?field.series_filter=trusty"},{default:p(()=>[...t[0]||(t[0]=[n("GNOME Team Staging PPA",-1)])]),_:1}),t[2]||(t[2]=n("確實涵蓋了升級用到的各種3.12版本包。開發者強調説，增加這個存檔會讓桌面系統‘運行流暢’，但現在包含的包並未‘準備好為大眾所使用’。",-1))]),t[18]||(t[18]=e("p",null,"這兒假設您是一個PPA清理工具的行家，以上的一切都已明瞭，請繼續向下。首先，讓我們核對並安裝已發佈的更新：",-1)),t[19]||(t[19]=e("pre",null,[e("code",null,`sudo apt-get update && sudo apt-get dist-upgrade
`)],-1)),t[20]||(t[20]=e("p",null,"按下回車鍵後等待安裝包程序。",-1)),t[21]||(t[21]=e("p",null,"一旦完成此過程或再沒有任何掛起的更新，就可以增加 GNOME Team Staging PPA了。為實現這項操作，打開新的命令列窗口輸入以下命令：",-1)),t[22]||(t[22]=e("pre",null,[e("code",null,`sudo add-apt-repository ppa:gnome3-team/gnome3-staging

sudo apt-get update && sudo apt-get dist-upgrade
`)],-1)),t[23]||(t[23]=e("p",null,"升級過程開始前需要輸入密碼，同時需要注意此過程中命令列提示的信息。如果一切順利點擊‘y’鍵確認安裝。",-1)),t[24]||(t[24]=e("h4",{id:"附加內容",tabindex:"-1"},[n("附加內容 "),e("a",{class:"header-anchor",href:"#附加內容","aria-label":"Permalink to “附加內容”"},"​")],-1)),e("p",null,[t[4]||(t[4]=n("為體驗真實的GNOME環境也許你想獲取一些新的GNOME應用，例如",-1)),u(a,{href:"http://www.omgubuntu.co.uk/2014/03/top-12-features-gnome-3-12"},{default:p(()=>[...t[3]||(t[3]=[n("Polari IRC客户端、GNOME地圖和GNOME網頁瀏覽器",-1)])]),_:1}),t[5]||(t[5]=n("。安裝這三個應用需要運行如下的命令：",-1))]),t[25]||(t[25]=o(`<pre><code>sudo apt-get install epiphany-browser gnome-maps polari -y
</code></pre><p>在這些都安裝完成之後，你就可以安全的重啓了！</p><h3 id="善後服務" tabindex="-1">善後服務 <a class="header-anchor" href="#善後服務" aria-label="Permalink to “善後服務”">​</a></h3><h4 id="登錄" tabindex="-1">登錄 <a class="header-anchor" href="#登錄" aria-label="Permalink to “登錄”">​</a></h4><p>如果你之前使用Unity,Xfce或別的桌面環境，不要忘記登錄前從登錄界面選擇GNOME會話。</p><h4 id="回顧" tabindex="-1">回顧 <a class="header-anchor" href="#回顧" aria-label="Permalink to “回顧”">​</a></h4><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/04/gnome-aspps.jpg" alt="GNOME Weather &amp; GNOME Maps in 3.12 3.12版GNOME天氣&amp;GNOME地圖"></p><p>對我自己來説，Ubuntu 14.04下運行GNOME 3.12很流暢。升級後沒有出現任何諸如性能下降的問題，儘管我確實見到過在打開活動窗口時的奇怪罕見的顯示故障，並且在一個應用下發生的間歇性陰影消失現象。但隨着錯誤不斷消除這些都不是大問題。</p><p>3.12版本的性能等同於GNOME3.10；應用的打開方式交互性強且體驗並沒有明顯下降。</p><p>所有新的GNOME影音應用在PPA上並沒有現成的包，這讓人有點失望。當然有理由解釋這點(很可能需要新版本的視頻解碼器)。此外仍要注意的是一些GNOME擴展包在升級後不能繼續工作。</p><p>當然3.12因為測試不足，其中存在錯誤不可避免。若用户要求穩定性（或者希望保持系統工作時的高度統一和完整），可以繼續支持已通過測試的GNOME 3.10版本。</p><h3 id="從gnome-3-12-降至3-10版本" tabindex="-1">從GNOME 3.12 降至3.10版本 <a class="header-anchor" href="#從gnome-3-12-降至3-10版本" aria-label="Permalink to “從GNOME 3.12 降至3.10版本”">​</a></h3><p>但是如果想要體驗閃閃亮的新功能及最新發布的GNOME應用，那就試一試PPA平台吧。如果遇到了錯誤可以隨時使用PPA清理工具來降級至穩定版本。</p><pre><code>sudo apt-get install ppa-purge

sudo ppa-purge ppa:gnome3-team/gnome3-staging
</code></pre><hr>`,15)),e("p",null,[t[7]||(t[7]=n("via: ",-1)),u(a,{href:"http://www.omgubuntu.co.uk/2014/05/upgrade-gnome-3-12-ubuntu-14-04"},{default:p(()=>[...t[6]||(t[6]=[n("http://www.omgubuntu.co.uk/2014/05/upgrade-gnome-3-12-ubuntu-14-04",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=n("譯者：",-1)),u(a,{href:"https://github.com/icybreaker"},{default:p(()=>[...t[8]||(t[8]=[n("icybreaker",-1)])]),_:1}),t[11]||(t[11]=n(" 校對：",-1)),u(a,{href:"https://github.com/wxy"},{default:p(()=>[...t[9]||(t[9]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=n("本文由 ",-1)),u(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[12]||(t[12]=[n("LCTT",-1)])]),_:1}),t[15]||(t[15]=n(" 原創翻譯，",-1)),u(a,{href:"http://linux.cn/"},{default:p(()=>[...t[13]||(t[13]=[n("Linux中國",-1)])]),_:1}),t[16]||(t[16]=n(" 榮譽推出",-1))])])}const f=r(d,[["render",g]]);export{T as __pageData,f as default};
